import assert from 'node:assert/strict';
import {Client,base,requests,transport,server,setActions,held,until,delay} from './codex-fixture';
const home=base+'/lifecycle-'+Date.now();let c=new Client(home,true,'',false);const modelCalls=()=>requests.filter(r=>r.generate!==false).length;
try{
 await c.init();const {thread}=await c.start();let started=await c.turn(thread.id,'first saved input');assert.equal((await c.done(started.turn.id)).status,'completed');
 setActions('hold');started=await c.turn(thread.id,'active input to steer');await until(()=>held.length===1);const active=started.turn.id;
 await assert.rejects(()=>c.call('turn/steer',{threadId:thread.id,expectedTurnId:'stale-turn',input:[{type:'text',text:'wrong steering'}]}));
 const accepted=await c.call('turn/steer',{threadId:thread.id,expectedTurnId:active,input:[{type:'text',text:'accepted steering marker'}]});assert.equal(accepted.turnId,active);held[0].respond();assert.equal((await c.done(active)).status,'completed');assert.equal(c.events.filter(e=>e.method==='turn/started'&&e.params.turn.id===active).length,1);assert.ok(requests.some(r=>JSON.stringify(r.input).includes('accepted steering marker')));
 await assert.rejects(()=>c.call('turn/steer',{threadId:thread.id,expectedTurnId:active,input:[{type:'text',text:'idle steering'}]}));
 setActions('hold');started=await c.turn(thread.id,'input to interrupt');await until(()=>held.length===2);await c.call('turn/steer',{threadId:thread.id,expectedTurnId:started.turn.id,input:[{type:'text',text:'pending steer to cancel'}]});const ack=await c.call('turn/interrupt',{threadId:thread.id,turnId:started.turn.id});assert.deepEqual(ack,{});assert.equal((await c.done(started.turn.id)).status,'interrupted');const afterStop=modelCalls();await delay(200);assert.equal(modelCalls(),afterStop);
 started=await c.turn(thread.id,'fresh after interrupt');assert.equal((await c.done(started.turn.id)).status,'completed');const fresh=requests.filter(r=>r.generate!==false).at(-1);const cancelledSteerInContext=JSON.stringify(fresh.input).includes('pending steer to cancel');assert.equal(cancelledSteerInContext,false);
 await c.close();const before=modelCalls();c=new Client(home,true,'',false);await c.init();await c.call('thread/read',{threadId:thread.id,includeTurns:false});assert.equal(modelCalls(),before);await c.call('thread/resume',{threadId:thread.id,excludeTurns:true});await delay(200);assert.equal(modelCalls(),before);started=await c.turn(thread.id,'fresh after owner reopen');assert.equal((await c.done(started.turn.id)).status,'completed');assert.ok(JSON.stringify(requests.filter(r=>r.generate!==false).at(-1).input).includes('first saved input'));
 await assert.rejects(()=>c.call('thread/resume',{threadId:'00000000-0000-0000-0000-000000000000',excludeTurns:true}));
 console.log(JSON.stringify({case:'Codex-app-server-lifecycle',retainedThread:true,correctSteerSameTurn:true,staleAndIdleSteerRejected:true,interruptAckThenTerminal:true,noAutoWorkAfterInterrupt:true,cancelledSteerInFreshContext:cancelledSteerInContext,readAndResumeInert:true,restoredContext:true,missingThreadRejected:true,modelCalls:modelCalls(),transport:transport()}));
}finally{await c.close();server.stop(true)}
